#!/usr/bin/env bash
# Generates the per-type spec files under Untrusted/Proofs/ from one template
# per shape of generated function. The proofs are identical up to type names,
# so they are written once here instead of 170 times by hand.
#
# Usage: proofs/scripts/gen_specs.sh   (from anywhere)
set -euo pipefail

out_dir="$(cd "$(dirname "$0")/.." && pwd)/Untrusted/Proofs"
mkdir -p "$out_dir"

unsigned=(U8 U16 U32 U64 U128 Usize)
signed=(I8 I16 I32 I64 I128 Isize)

is_signed() { [[ $1 == I* ]]; }

header() {
  cat <<EOF
-- THIS FILE WAS GENERATED BY \`proofs/scripts/gen_specs.sh\`; edit the script instead.
$1
open Aeneas Aeneas.Std Result

namespace $2
EOF
}

# --- Integer conversions ------------------------------------------------------

int_spec() {
  local src=$1 tgt=$2 kind ok range
  if is_signed "$src"; then
    if is_signed "$tgt"; then kind=II ok='out.val = input.val'
    else kind=IU ok='(out.val : Int) = input.val'; fi
  else
    if is_signed "$tgt"; then kind=UI ok='out.val = (input.val : Int)'
    else kind=UU ok='(out.val : Int) = input.val'; fi
  fi
  if is_signed "$tgt"; then range=IInRange; else range=UInRange; fi
  local f="$tgt.Insts.UntrustedValidate${src}ValidationError.validate"
  cat <<EOF

/-- **Spec theorem for \`untrusted::int::{impl Validate<${src,,}> for ${tgt,,}>}::validate\`**
Succeeds exactly when \`input\` is representable in \`${tgt,,}\`, and then preserves its value. -/
@[step]
theorem $f.spec (input : $src) :
    $f input
      ⦃ (r : core.result.Result $tgt ValidationError) =>
        match r with
        | .Ok out => $ok
        | .Err e => e = .OutOfRange ∧ ¬ $range .$tgt input.val ⦄ := by
  rw [show $f input = generic.validate$kind .$src .$tgt input from rfl]
  apply WP.spec_mono (generic.validate$kind.spec .$src .$tgt input)
  rintro (_ | _) <;> exact id
EOF
}

{
  header "import Untrusted.Generic" untrusted
  for src in "${unsigned[@]}" "${signed[@]}"; do
    for tgt in "${unsigned[@]}" "${signed[@]}"; do
      [[ $src == "$tgt" ]] || int_spec "$src" "$tgt"
    done
  done
  printf '\nend untrusted\n'
} > "$out_dir/Int.lean"

# --- Byte decoders ------------------------------------------------------------

# The shared prefix of the generated names.
inst() { echo "$1$2.Insts.UntrustedValidateSharedASliceU8ValidationError"; }

# Postcondition on the decoded value `x`: unsigned values are the number
# denoted by the bytes; signed values are its two's-complement reading.
value_post() {
  local t=$1 bits=$2 num=$3
  if is_signed "$t"; then echo "(x : $t).bv = BitVec.ofNat $bits ($num input.val)"
  else echo "(x : $t).val = $num input.val"; fi
}

decoder_spec() {
  local order=$1 t=$2 n=$3 body=$4 num
  if [[ $order == BigEndian ]]; then num=beNat; else num=leNat; fi
  local f; f="$(inst "$order" "$t").validate"
  local bits=$((8 * n)) order_rs
  order_rs=$([[ $order == BigEndian ]] && echo big || echo little)
  cat <<EOF

/-- **Spec theorem for \`untrusted::bytes::{impl Validate<&[u8]> for $order<${t,,}>}::validate\`**
Accepts exactly the inputs of length $n and decodes them as a $order_rs-endian \`${t,,}\`. -/
@[step]
theorem $f.spec (input : Slice U8) :
    $f input
      ⦃ (r : core.result.Result ($order $t) ValidationError) =>
        match r with
        | .Ok x => input.length = $n ∧ $(value_post "$t" "$bits" "$num")
        | .Err e => input.length ≠ $n ∧ e = .LengthMismatch $n#usize input.len ⦄ := by
  unfold $f
  step as ⟨ r, r_post ⟩
  cases r
  · simp only [core.result.Result.Insts.CoreOpsTry.branch, bind_ok] at *
$body
  · simp [core.result.Result.Insts.CoreOpsTry.branch,
      core.result.Result.Insts.CoreOpsTry_traitFromResidualResult.from_residual] at *
    agrind
EOF
}

single_byte_body() {
  local order=$1 t=$2 lemma
  if [[ $order == BigEndian ]]; then lemma=beNat_singleton; else lemma=leNat_singleton; fi
  if is_signed "$t"; then
    cat <<EOF
    step*
    refine ⟨r_post, ?_⟩
    rw [i1_post, $lemma _ r_post, ← i_post]
    apply BitVec.eq_of_toNat_eq
    simp [UScalar.hcast_bv_eq]
EOF
  else
    cat <<EOF
    step*
    simp [*, $lemma _ r_post]
EOF
  fi
}

multi_byte_body() {
  local order=$1 t=$2 pre
  # The loop starts with nothing accumulated.
  if [[ $order == BigEndian ]]; then pre='· simp'
  else pre='· rw [List.drop_eq_nil_of_le (by scalar_tac)]; simp'; fi
  if is_signed "$t"; then
    cat <<EOF
    step as ⟨ acc, acc_post ⟩
    $pre
    step*
    refine ⟨r_post, ?_⟩
    rw [i_post]
    apply BitVec.eq_of_toNat_eq
    simp [UScalar.hcast_bv_eq]
    rw [← acc_post]
    exact (Nat.mod_eq_of_lt (by scalar_tac)).symm
EOF
  else
    cat <<EOF
    step as ⟨ acc, acc_post ⟩
    $pre
    simp [*]
EOF
  fi
}

# Loop over the input bytes, accumulating into the unsigned type `$acc`.
be_loop_spec() {
  local t=$1 acc=$2 n=$3
  local f; f="$(inst BigEndian "$t").validate_loop"
  cat <<EOF

/-- After consuming the first \`i\` bytes, \`acc\` holds their big-endian value. -/
@[step]
theorem $f.spec
    (input : Slice U8) (acc : $acc) (i : Usize)
    (hlen : input.length = $n) (hi : i.val ≤ $n) (hacc : acc.val = beNat (input.val.take i.val)) :
    $f input acc i
      ⦃ (r : $acc) => r.val = beNat input.val ⦄ := by
  unfold $f
  split
  · step*
    rw [acc1_post, UScalar.val_or, i1_post, i3_post, i4_post, beNat_take_succ _ _ (by scalar_tac),
      ← hacc, i2_post]
    simp only [U8.cast_${acc}_val_eq]
    apply shl8_or _ _ _ (by scalar_tac)
    rw [hacc]
    have := beNat_mul_lt (input.val.take i.val) $n (by simp; scalar_tac)
    simp only [$acc.size, $acc.numBits] at *
    scalar_tac
  · step*
    rw [hacc, List.take_of_length_le (by scalar_tac)]
termination_by $n - i.val
decreasing_by scalar_decr_tac
EOF
}

le_loop_spec() {
  local t=$1 acc=$2 n=$3
  local f; f="$(inst LittleEndian "$t").validate_loop"
  cat <<EOF

/-- With the bytes from \`i\` on consumed, \`acc\` holds their little-endian value. -/
@[step]
theorem $f.spec
    (input : Slice U8) (acc : $acc) (i : Usize)
    (hlen : input.length = $n) (hi : i.val ≤ $n)
    (hacc : acc.val = beNat (input.val.drop i.val).reverse) :
    $f input acc i
      ⦃ (r : $acc) => r.val = leNat input.val ⦄ := by
  unfold $f
  split
  · step*
    rw [acc1_post, UScalar.val_or, i2_post, i4_post, i3_post, beNat_drop _ _ (by scalar_tac),
      show i1.val + 1 = i.val by scalar_tac, ← hacc]
    simp only [U8.cast_${acc}_val_eq]
    apply shl8_or _ _ _ (by scalar_tac)
    rw [hacc]
    have := beNat_mul_lt (input.val.drop i.val).reverse $n (by simp; scalar_tac)
    simp only [$acc.size, $acc.numBits] at *
    scalar_tac
  · step*
    rw [hacc, leNat, show i.val = 0 by scalar_tac, List.drop_zero]
termination_by i.val
decreasing_by scalar_decr_tac
EOF
}

{
  header "import Untrusted.Funs
import Untrusted.Spec
import Untrusted.Proofs.Core" untrusted.bytes
  for order in BigEndian LittleEndian; do
    for t in U8 I8; do
      decoder_spec "$order" "$t" 1 "$(single_byte_body "$order" "$t")"
    done
    for spec in U16:U16:2 U32:U32:4 U64:U64:8 U128:U128:16 I16:U16:2 I32:U32:4 I64:U64:8 I128:U128:16; do
      IFS=: read -r t acc n <<< "$spec"
      if [[ $order == BigEndian ]]; then be_loop_spec "$t" "$acc" "$n"
      else le_loop_spec "$t" "$acc" "$n"; fi
      decoder_spec "$order" "$t" "$n" "$(multi_byte_body "$order" "$t")"
    done
  done
  printf '\nend untrusted.bytes\n'
} > "$out_dir/Bytes.lean"

echo "Wrote $out_dir/Int.lean and $out_dir/Bytes.lean"
